#!/usr/bin/env python3
# lifeplus-site-v3: スマホの配置を整える・ボディケアのメニュー・接骨院の文言
# 何度流しても同じ。元のファイルが想定と違うときは何も変えずに止まる
import hashlib, zlib, base64, json, os, shutil, sys, time
FILES = json.loads('{"docs/site.css": {"old": "c8356a4bc49f354adbb82fdfba4362c7", "new": "6d774dcdf128eb08baa399913b070e7c", "data": ""}, "docs/index.html": {"old": "8f7f20657acd7197ad01d337892d8291", "new": "0e318834a9416c9cb08bd64c9eb17063", "data": ""}, "docs/dayservice/index.html": {"old": "98431b97bae8d4b99f4990a4dd382864", "new": "9a63d70ea3942bdc76756b5e9ee4edb2", "data": ""}, "docs/sekkotsu/index.html": {"old": "f84c15467d224449fd22f67b127d7754", "new": "7a90b53ea8cb153e01b5171459dc4436", "data": ""}, "docs/bodycare/index.html": {"old": "5e67b66095775f53f646ed2a28057163", "new": "ff8673dc1d74d58d94e59677171ae627", "data": ""}, "tests/e2e_site_test.py": {"old": "051a66a2cd73487f3b98dd81708f1688", "new": "3126ed615d2c08ba70921730920bcbf7", "data": ""}, "README.md": {"old": "38221e5d10a560193750a580ff3c9534", "new": "3abbdce0424f3271ade8ff771ed2e692", "data": ""}}')
here = os.path.dirname(os.path.abspath(__file__)); os.chdir(here)
md5 = lambda b: hashlib.md5(b).hexdigest()
todo = []
for p, f in FILES.items():
    cur = md5(open(p, "rb").read()) if os.path.exists(p) else None
    if cur == f["new"]: print("済み", p); continue
    if cur != f["old"]: print("止めました：", p, "が想定と違います（", cur, "）。何も変えていません"); sys.exit(1)
    todo.append(p)
ts = time.strftime("%Y%m%d%H%M%S")
for p in todo:
    shutil.copy2(p, p + ".bak_" + ts)
    b = zlib.decompress(base64.b64decode(FILES[p]["data"]))
    assert md5(b) == FILES[p]["new"]
    open(p, "wb").write(b); print("更新", p)
print("lifeplus-site-v3 OK")
